(()=>{const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=v=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-IN',{maximumFractionDigits:2});
window.FyersStockScreener={mount(host,{onChart,onPlan}){
 let list=[],quotes=[],rows=[],running=false,active=true,run=0,search=0;try{const d=JSON.parse(localStorage.getItem('radar.fyersStockList')||'[]');if(Array.isArray(d))list=[...new Set(d.filter(s=>typeof s==='string'&&/^(NSE|BSE):[A-Z0-9&._-]{2,65}$/.test(s)))].slice(0,20)}catch{}
 host.innerHTML='<div class="market-controls"><label>Stock name / ticker<input id="fsQuery" placeholder="TCS or Tata Consultancy…" maxlength="80"></label><label>Exchange<select id="fsSegment"><option value="NSE_CM">NSE</option><option value="BSE_CM">BSE</option></select></label><button id="fsFind">Search stocks</button><label>Matching instruments<select id="fsMatches"><option value="">Search first</option></select></label><button id="fsAdd">Add selected stock</button></div><p id="fsSearchStatus" role="status"></p><div class="market-controls"><button id="fsQuotes">Refresh FYERS quotes</button><button id="fsScan">Scan my stocks</button><button id="fsStop" disabled>Stop scan</button><label>Quote filter<select id="fsFilter"><option value="all">All</option><option value="up">Positive daily change</option><option value="down">Negative daily change</option></select></label></div><p id="fsStatus" role="status">Search and add stocks to begin. Your list is saved in this browser.</p><div id="fsList"></div><h3>Strategy scan results</h3><div id="fsResults"></div><p class="small-note">Runs while this page is open. Up to 20 selected instruments, checked one at a time. Closed-candle strategies and their limitations are shown per instrument; this is not an all-exchange or background stock scan. Broker/data permissions and source timestamps apply.</p>';
 const $=id=>host.querySelector('#'+id),message=t=>$('fsStatus').textContent=t;function save(){try{localStorage.setItem('radar.fyersStockList',JSON.stringify(list))}catch{message('Browser storage unavailable; list lasts for this session.')}}
 async function api(path){const response=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(path.includes('/scan?')?60000:25000)});const d=await response.json();if(!d||typeof d!=='object'||!response.ok||d.error)throw Error(d?.error||'FYERS data unavailable.');return d}
 function draw(){const filtered=list.filter(symbol=>{const q=quotes.find(q=>q?.symbol===symbol);return $('fsFilter').value==='up'?q?.changePercent>0:$('fsFilter').value==='down'?q?.changePercent<0:true});$('fsList').innerHTML='<div class="market-table-scroll" tabindex="0" role="region" aria-label="Stock quote table"><table class="market-table"><thead><tr><th>Stock</th><th>Last price</th><th>Change %</th><th>Source time (IST)</th><th>Data</th><th>Actions</th></tr></thead><tbody>'+(filtered.map(symbol=>{const q=quotes.find(q=>q?.symbol===symbol),fresh=q?.valid&&Number.isFinite(q.at)&&q.at<=Date.now()+1000&&Date.now()-q.at<=15000;return '<tr><td>'+esc(symbol)+'</td><td>'+fmt(q?.price)+'</td><td>'+fmt(q?.changePercent)+'</td><td>'+esc(q?.at?new Date(q.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'Unavailable')+'</td><td>'+(q?(fresh?'Fresh snapshot':esc(q.error||'Last traded / not live')):'Not loaded')+'</td><td><button data-fs-chart="'+esc(symbol)+'">Chart</button><button data-fs-plan="'+esc(symbol)+'">Plans</button><button data-fs-remove="'+esc(symbol)+'" '+(running?'disabled':'')+'>Remove</button></td></tr>'}).join('')||'<tr><td colspan="6">'+(list.length?'No stocks match this filter.':'No stocks added yet.')+'</td></tr>')+'</tbody></table></div>';$('fsResults').innerHTML=rows.map(row=>'<section class="stock-card"><strong>'+esc(row.symbol)+'</strong><p>'+esc(row.error||'Completed strategy check')+'</p>'+(row.results||[]).map(r=>'<p><b>'+esc(r.strategy)+' · '+esc(r.status)+'</b> — '+esc(r.reason)+'</p>').join('')+'</section>').join('');$('fsScan').disabled=running||!list.length;$('fsQuotes').disabled=running||!list.length;$('fsAdd').disabled=running;$('fsStop').disabled=!running}
 $('fsFind').onclick=async()=>{const id=++search,segment=$('fsSegment').value,query=$('fsQuery').value.trim();$('fsFind').disabled=true;try{const d=await api('/api/fyers/instruments?segment='+segment+'&search='+encodeURIComponent(query));if(!active||id!==search)return;if(!Array.isArray(d.instruments))throw Error('Instrument list unavailable');$('fsMatches').innerHTML='<option value="">Choose stock</option>'+d.instruments.map(r=>'<option value="'+esc(r.symbol)+'">'+esc(r.symbol+' · '+r.name)+'</option>').join('');$('fsSearchStatus').textContent=d.total+' matches; first '+d.instruments.length+' shown.'}catch(e){if(active&&id===search)$('fsSearchStatus').textContent=e.message}finally{if(active&&id===search)$('fsFind').disabled=false}};
 $('fsQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('fsFind').click()}};$('fsSegment').onchange=()=>{search++;$('fsMatches').innerHTML='<option value="">Search this exchange</option>';$('fsFind').disabled=false};$('fsAdd').onclick=()=>{const symbol=$('fsMatches').value;if(!symbol)return message('Search and select a stock first.');if(list.includes(symbol))return message(symbol+' is already in your list.');if(list.length>=20)return message('Maximum 20 stocks per list. Remove one before adding another.');list.push(symbol);save();draw();message(symbol+' added. Refresh quotes or scan your stocks.')};
 $('fsQuotes').onclick=async()=>{if(running||!list.length)return;running=true;const id=++run;draw();try{const d=await api('/api/fyers/quotes?symbols='+encodeURIComponent(list.join(',')));if(!active||id!==run)return;if(!Array.isArray(d.quotes))throw Error('FYERS quote list unavailable');quotes=d.quotes;message('Quotes fetched '+new Date(d.asOf).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST. Check source timestamps.')}catch(e){if(active&&id===run)message(e.message)}finally{if(active&&id===run){running=false;draw()}}};
 $('fsScan').onclick=async()=>{if(running||!list.length)return;running=true;const id=++run,selected=list.slice();rows=[];draw();try{for(const symbol of selected){if(!active||id!==run)return;message('Scanning '+symbol+' · '+(rows.length+1)+' / '+selected.length);try{const d=await api('/api/fyers/scan?symbol='+encodeURIComponent(symbol));if(!active||id!==run)return;if(d.symbol!==symbol||!Array.isArray(d.results)||d.results.some(r=>!r||typeof r.strategy!=='string'||typeof r.status!=='string'||typeof r.reason!=='string'))throw Error('Invalid strategy result');rows.push({symbol,results:d.results,error:Array.isArray(d.errors)&&d.errors.length?d.errors.join(' · '):null})}catch(e){if(!active||id!==run)return;rows.push({symbol,error:e.message})}draw()}message('Scan completed: '+rows.filter(r=>r.results).length+' / '+selected.length+' instruments returned strategy results. Unavailable checks remain labelled.')}finally{if(active&&id===run){running=false;draw()}}};
 $('fsStop').onclick=()=>{run++;running=false;message('Scan stopped. Completed results are retained; the current server request may finish.');draw()};$('fsFilter').onchange=draw;const clickHandler=event=>{const b=event.target.closest('[data-fs-chart],[data-fs-plan],[data-fs-remove]');if(!b)return;if(b.dataset.fsChart)onChart(b.dataset.fsChart);if(b.dataset.fsPlan)onPlan(b.dataset.fsPlan);if(b.dataset.fsRemove&&!running){list=list.filter(s=>s!==b.dataset.fsRemove);quotes=quotes.filter(q=>q.symbol!==b.dataset.fsRemove);rows=rows.filter(r=>r.symbol!==b.dataset.fsRemove);save();draw()}};host.addEventListener('click',clickHandler);draw();return ()=>{active=false;run++;search++;host.removeEventListener('click',clickHandler)};
}};
})();
